class Skiplist {
    private static final int MAX_LEVEL = 16;
    private static final double P = 0.5;
    private int[] head;
    private int[][] next;
    private int[] val;
    private int[] level;
    private int size;
    private int curLevel;
    private java.util.Random rand;

    public Skiplist() {
        head = new int[MAX_LEVEL];
        java.util.Arrays.fill(head, -1);
        next = new int[80001][MAX_LEVEL];
        val = new int[80001];
        level = new int[80001];
        size = 0;
        curLevel = 0;
        rand = new java.util.Random();
    }

    private int randomLevel() {
        int lvl = 1;
        while (lvl < MAX_LEVEL && rand.nextDouble() < P) lvl++;
        return lvl;
    }

    public boolean search(int target) {
        int cur = -1;
        for (int i = curLevel - 1; i >= 0; i--) {
            int nxt = (cur == -1) ? head[i] : next[cur][i];
            while (nxt != -1 && val[nxt] < target) {
                cur = nxt;
                nxt = next[cur][i];
            }
            if (nxt != -1 && val[nxt] == target) return true;
        }
        return false;
    }

    public void add(int num) {
        int[] update = new int[MAX_LEVEL];
        java.util.Arrays.fill(update, -1);
        int cur = -1;
        for (int i = curLevel - 1; i >= 0; i--) {
            int nxt = (cur == -1) ? head[i] : next[cur][i];
            while (nxt != -1 && val[nxt] < num) {
                cur = nxt;
                nxt = next[cur][i];
            }
            update[i] = cur;
        }
        int lvl = randomLevel();
        if (lvl > curLevel) curLevel = lvl;
        int idx = size++;
        val[idx] = num;
        level[idx] = lvl;
        for (int i = 0; i < lvl; i++) {
            if (update[i] == -1) {
                next[idx][i] = head[i];
                head[i] = idx;
            } else {
                next[idx][i] = next[update[i]][i];
                next[update[i]][i] = idx;
            }
        }
    }

    public boolean erase(int num) {
        int[] update = new int[MAX_LEVEL];
        java.util.Arrays.fill(update, -1);
        int cur = -1;
        int target = -1;
        for (int i = curLevel - 1; i >= 0; i--) {
            int nxt = (cur == -1) ? head[i] : next[cur][i];
            while (nxt != -1 && val[nxt] < num) {
                cur = nxt;
                nxt = next[cur][i];
            }
            if (nxt != -1 && val[nxt] == num) target = nxt;
            update[i] = cur;
        }
        if (target == -1) return false;
        for (int i = 0; i < level[target]; i++) {
            if (update[i] == -1) {
                head[i] = next[target][i];
            } else {
                next[update[i]][i] = next[target][i];
            }
        }
        while (curLevel > 0 && head[curLevel - 1] == -1) curLevel--;
        return true;
    }
}

import java.util.*;

class Skiplist {
    private List<Integer> list;
    public Skiplist() {
        list = new ArrayList();
    }
    public boolean search(int target) {
        int idx = Collections.binarySearch(list, target);
        return idx >= 0;
    }
    public void add(int num) {
        int idx = Collections.binarySearch(list, num);
        if (idx < 0) idx = -(idx + 1);
        list.add(idx, num);
    }
    public boolean erase(int num) {
        int idx = Collections.binarySearch(list, num);
        if (idx < 0) return false;
        list.remove(idx);
        return true;
    }
}
